'use client'

import { useState, useEffect } from 'react'
import { LineChart, Line, ResponsiveContainer, Tooltip } from 'recharts'
import { Thermometer, Heart, Wind, Gauge, Activity } from 'lucide-react'

export function VitalSigns() {
  const [animatedValues, setAnimatedValues] = useState({
    temp: 0,
    hr: 0,
    spo2: 0,
    sbp: 0,
    rr: 0,
  })

  const vitalSigns = [
    {
      id: 'temperature',
      label: 'Temperature',
      value: 98.6,
      unit: '°F',
      icon: Thermometer,
      color: 'from-orange-100 to-orange-50',
      iconColor: 'text-orange-600',
      borderColor: 'border-orange-200',
      data: [
        { time: '18:00', value: 98.4 },
        { time: '18:15', value: 98.5 },
        { time: '18:30', value: 98.6 },
        { time: '18:45', value: 98.5 },
        { time: '19:00', value: 98.6 },
      ],
    },
    {
      id: 'heart-rate',
      label: 'Heart Rate',
      value: 72,
      unit: 'bpm',
      icon: Heart,
      color: 'from-red-100 to-red-50',
      iconColor: 'text-red-600',
      borderColor: 'border-red-200',
      data: [
        { time: '18:00', value: 70 },
        { time: '18:15', value: 71 },
        { time: '18:30', value: 72 },
        { time: '18:45', value: 71 },
        { time: '19:00', value: 72 },
      ],
    },
    {
      id: 'spo2',
      label: 'SpO₂',
      value: 98,
      unit: '%',
      icon: Wind,
      color: 'from-blue-100 to-blue-50',
      iconColor: 'text-blue-600',
      borderColor: 'border-blue-200',
      data: [
        { time: '18:00', value: 97 },
        { time: '18:15', value: 98 },
        { time: '18:30', value: 98 },
        { time: '18:45', value: 98 },
        { time: '19:00', value: 98 },
      ],
    },
    {
      id: 'blood-pressure',
      label: 'Blood Pressure',
      value: 120,
      unit: 'mmHg',
      secondValue: 80,
      icon: Gauge,
      color: 'from-purple-100 to-purple-50',
      iconColor: 'text-purple-600',
      borderColor: 'border-purple-200',
      data: [
        { time: '18:00', value: 118 },
        { time: '18:15', value: 119 },
        { time: '18:30', value: 120 },
        { time: '18:45', value: 119 },
        { time: '19:00', value: 120 },
      ],
    },
    {
      id: 'respiratory',
      label: 'Respiratory Rate',
      value: 16,
      unit: 'bpm',
      icon: Activity,
      color: 'from-emerald-100 to-emerald-50',
      iconColor: 'text-emerald-600',
      borderColor: 'border-emerald-200',
      data: [
        { time: '18:00', value: 15 },
        { time: '18:15', value: 16 },
        { time: '18:30', value: 16 },
        { time: '18:45', value: 16 },
        { time: '19:00', value: 16 },
      ],
    },
  ]

  useEffect(() => {
    const timers = [
      setTimeout(() => setAnimatedValues((v) => ({ ...v, temp: 98.6 })), 100),
      setTimeout(() => setAnimatedValues((v) => ({ ...v, hr: 72 })), 200),
      setTimeout(() => setAnimatedValues((v) => ({ ...v, spo2: 98 })), 300),
      setTimeout(() => setAnimatedValues((v) => ({ ...v, sbp: 120 })), 400),
      setTimeout(() => setAnimatedValues((v) => ({ ...v, rr: 16 })), 500),
    ]
    return () => timers.forEach((timer) => clearTimeout(timer))
  }, [])

  return (
    <div className="space-y-4">
      <h2 className="text-lg font-bold text-slate-900">Vital Signs</h2>
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-5 gap-4">
        {vitalSigns.map((vital, index) => {
          const Icon = vital.icon
          return (
            <div
              key={vital.id}
              className={`bg-gradient-to-br ${vital.color} border ${vital.borderColor} rounded-lg p-4 hover:shadow-lg transition-all duration-300 animate-fade-in`}
              style={{ animationDelay: `${index * 100}ms` }}
            >
              {/* Header */}
              <div className="flex items-start justify-between mb-3">
                <span className="text-xs font-semibold text-slate-600 uppercase">{vital.label}</span>
                <Icon className={`w-5 h-5 ${vital.iconColor}`} />
              </div>

              {/* Value */}
              <div className="mb-3">
                <div className="text-2xl font-bold text-slate-900">
                  {vital.id === 'blood-pressure' ? `${vital.value}/${vital.secondValue}` : vital.value}
                </div>
                <p className="text-xs text-slate-600 font-medium">{vital.unit}</p>
              </div>

              {/* Mini Chart */}
              <ResponsiveContainer width="100%" height={40}>
                <LineChart data={vital.data}>
                  <Tooltip
                    contentStyle={{
                      backgroundColor: 'rgba(255, 255, 255, 0.95)',
                      border: '1px solid #e2e8f0',
                      borderRadius: '4px',
                      fontSize: '12px',
                    }}
                  />
                  <Line
                    type="monotone"
                    dataKey="value"
                    stroke={
                      vital.id === 'temperature'
                        ? '#ea580c'
                        : vital.id === 'heart-rate'
                          ? '#dc2626'
                          : vital.id === 'spo2'
                            ? '#2563eb'
                            : vital.id === 'blood-pressure'
                              ? '#9333ea'
                              : '#059669'
                    }
                    strokeWidth={2}
                    dot={false}
                    isAnimationActive={false}
                  />
                </LineChart>
              </ResponsiveContainer>

              {/* Update time */}
              <p className="text-xs text-slate-500 mt-2">Updated 2 min ago</p>
            </div>
          )
        })}
      </div>
    </div>
  )
}
